"""Task-local weekly report guidance with native capability delegation."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


GUIDANCE = """依据当次四类材料写一份可直接转发的周报。形成指标表达时对照本次提供的 weekly-report-number-display；生成最终回复时对照 weekly-report-delivery 的回复形态。
1. 以当次工作规则、本周记录、上周周报和指标口径表为准；完整读过且仍适用的材料直接复用，只补缺失或更新部分。上周仅用于本次要求的比较与跟进。
2. 先完成本周出现的口径表指标明细：按本次表映射标准名，以原始本周数和可用上周数算变化，再形成“标准名＋展示数值＋数量级（适用时）＋标准单位＋变化或缺基数标注”的完整表达。完整数字规则不缩写；通用阈值逐项用于人数、金额等全部适用数值类指标；万是数量级，换算后仍保留人、元等标准单位。精度、变化算法和无上周数的标注取自当次规则，变化不用舍入展示数重算。
3. 从上述明细提炼一句结论，放到实际首行；结论及其他叙述复用明细的标准名和完整数值表达，不从零散记录重新摘取别名。结论不替代必写明细。按规定段落保留全部待决事项和下周计划，已确认事项不混入待决段。
4. 对最终要交出的整份周报核对事实、首行、标题、顺序和禁用词，并用现有计算能力按当次字符口径计数，包含首行及标题。超限先删非必需叙述及重复表达，保留必写内容；改动后重算。无需另存表格或强制读写草稿，可合并已有计算。
5. 回复沿用这份周报，从业务首行到末段，不再概述核对结果。当前未要求附件，只回复这一份正文。材料缺失、冲突、无法读取或普通核对失败时，按当次规则交出有依据的部分，在相关段内保留必要缺口，不编造事实或核验结果，不以等待和计划替代周报。"""

SKILL_NAME = "weekly-report-delivery"
NUMBER_SKILL_NAME = "weekly-report-number-display"
SKILL_SOURCE = "curator-capability"
CASE_NAMES = (SKILL_NAME, NUMBER_SKILL_NAME)
MISSING_CASE_GUIDANCE = (
    "以下案例本次不可用：{names}。直接依据当次工作规则处理相应步骤，"
    "不声称已完成这些案例对照；不把本提示写入周报。"
)


class WeeklyReportCapability(CapabilityStrategy):
    """Supply delivery examples without owning business facts or session state."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets["weekly_delivery_skill.md"]},
                source="weekly-report-delivery-examples",
            ),
            SkillContribution(
                name=NUMBER_SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets["weekly_number_display_skill.md"]},
                source="weekly-report-number-display-examples",
            ),
        )

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        available_cases: set[tuple[str, str]] = set()
        missing: list[str] = []
        for name in CASE_NAMES:
            examples = [
                skill for skill in request.skills
                if skill.name == name and skill.source == SKILL_SOURCE
            ]
            if len(examples) > 1:
                raise ValueError(f"ambiguous {name} skill identity")
            if examples and examples[0].available:
                available_cases.add((SKILL_SOURCE, name))
            else:
                missing.append(name)

        guidance = GUIDANCE
        if missing:
            guidance += "\n" + MISSING_CASE_GUIDANCE.format(names="、".join(missing))
        if not available_cases:
            return CapabilitySelection(tools=None, skills=None, guidance=guidance)

        selected: list[SkillSelection] = []
        seen: set[tuple[str, str]] = set()
        for skill in request.skills:
            identity = (skill.source, skill.name)
            if not skill.available or identity in seen:
                continue
            seen.add(identity)
            selected.append(
                SkillSelection(
                    name=skill.name,
                    source=skill.source,
                    delivery="body" if identity in available_cases else "catalog",
                )
            )
        return CapabilitySelection(tools=None, skills=tuple(selected), guidance=guidance)


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> WeeklyReportCapability:
    """Bind the host registrar; leave task identity and checkpoint untouched."""
    return WeeklyReportCapability(registrar)
